"""Build editable Quarto/Typst and a readable Markdown manuscript from JSON."""
from pathlib import Path
import json,csv,math
R=Path(__file__).resolve().parent.parent
def read(p): return json.loads((R/p).read_text(encoding='utf-8-sig'))
lessons=sum((read(f'production/p{g}.json') for g in (1,2,3)),[])
(R/'production/lessons.json').write_text(json.dumps(lessons,ensure_ascii=False,indent=2),encoding='utf-8')
def S(s):return json.dumps(str(s),ensure_ascii=False)
def T(s,size=None,bold=False):
    return '#block(above: 0pt, below: 1mm)[#text('+('size: '+str(size)+'pt, ' if size else '')+('weight: "bold", ' if bold else '')+S(s)+')]\n'
def head(k,t):return f'#titlebar({S(k)}, {S(t)})\n'
def sec(n,t):return f'#section({S(n)}, {S(t)})\n'
def note(t,b):return f'#note({S(t)}, {S(b)})\n'
def para(s):return T(s)+'\n#v(3mm)\n'
def img(p,h=40):return f'#image({S(p)}, width: 100%, height: {h}mm, fit: "contain", alt: {S("Original illustrative artwork or exact teaching diagram; see credits and source manifest.")})\n#v(2mm)\n'
pages=[]
def page(label,body,size=12):pages.append(dict(label=label,body=f'#set text(size: {size}pt)\n'+body))
def Q(id,prompt,space=11):return f'#question({S(id)}, {S(prompt)}, space: {space}mm)\n'
page('cover', '#v(10mm)\n'+T('GOMBE',43,True)+T('MATHEMATICS',29,True)+T('BOOK 1',24,True)+'#v(5mm)\n'+T('Primary 1 • Primary 2 • Primary 3',16)+img('artwork/school.png',110)+T('Count • Explore • Make • Explain',18,True)+'#v(6mm)\n'+T('An English write-in mathematics book',14)+T('Full-colour review edition · October 2026',11)+note('For educational review','Curriculum lineage: verified 2012 NERDC reference. Current revised-curriculum comparison, local review and physical print checks remain pending. This PDF is not a press-approved export.'))
page('welcome',head('START HERE','Mathematics belongs to everyone')+para('Mathematics helps us count, share, compare, measure and make decisions. Explore it with Amina, Musa, Zainab and Daniel in everyday school, home, garden and pretend-market stories.')+para('This is one write-in volume for three classes. Begin in the part that matches your learning needs. It is fine to revisit an earlier idea. Explain by speaking, pointing, drawing, using objects or writing.')+para('My name: ____________________________________')+para('My school: ___________________________________')+para('My class: ____________________________________')+note('Publication status','Original manuscript and AI-assisted original artwork prepared for review. No author, publisher, ISBN, NERDC approval or Gombe adoption is asserted. Final publication details belong to the commissioning publisher.')+para('The source brief GombeTextbook.txt is preserved. Local contexts are fictional everyday experiences, not verified depictions of named schools, markets or landmarks. The single named landscape photograph is credited from its verified source record. Contemporary shopping prices are not asserted.')+para('Teachers: guidance, worked answers, additional objective checks, the historical curriculum crosswalk, glossary, credits and the Book 2 preview are inside this volume.'))
page('how',head('START HERE','How to use this book')+sec('1','Look and Talk')+para('Look at the situation. Talk about what you notice and what you could find out. Decorative story pictures do not supply exact counts.')+sec('2','Learn Together')+para('Read a short explanation. Use objects and the worked example. Exact diagrams have clear quantities; their printed scale is not a measuring tool.')+sec('3','Try It')+para('Complete questions 1 to 4. Use the spaces for writing, drawing or working. A teacher may read instructions aloud.')+sec('4','Play or Make')+para('Work with inexpensive safe materials. Take turns. A partner checks your method, not only your answer.')+sec('5','Check Yourself')+para('Complete questions 5 and 6. Tell how you know. Mark: I can do this / I need more practice. Return to objects when needed.')+note('Read in number order','Read the main column before the sidebar. WORDS gives vocabulary, HINT helps pupils, and TEACHER is for adults. Questions use lesson ID plus question number in the answer key.')+note('Care for one another','Use large clean counters, blunt sticks, paper and unbreakable containers. Adults handle cutting and supervise water activities. Never taste materials. Respect privacy and allow fictional survey data.'))
page('friends',head('OUR STORY FRIENDS','Meet the team')+img('artwork/characters.png',105)+para('Amina enjoys organising and explaining. Musa asks useful questions. Zainab tests patterns and designs. Daniel likes checking methods. Every friend can learn, help and make mistakes.')+para('Our friends are fictional. Their clothes and routines do not represent every family in Gombe. Share examples from your own experience when you wish. Everyone belongs in a mathematics lesson.')+note('Your turn','Draw yourself learning with the team. What would you like to find out?')+'#v(35mm)\n'+ '#line(length: 100%, stroke: 0.5pt)\n')
page('gombe-photo',head('LOOK AROUND US','A landscape in Gombe')+img('artwork/kilang-hill.jpg',105)+para('This photograph is identified by its photographer as Kilang Hill in Kaltungo Local Government Area. A photograph shows one place at one moment; Gombe has many different everyday surroundings.')+para('Talk together: point to a curved outline. Find something that looks taller than a nearby object. Can a photograph alone tell its exact height? We need a real measurement to know.')+note('PHOTO CREDIT','Kilang Hill, Huzaifakumo, 15 October 2022. Wikimedia Commons. CC BY-SA 4.0. Reproduced unchanged, fitted proportionally. Source: https://commons.wikimedia.org/wiki/File:Kilang_Hill.jpg . Licence: https://creativecommons.org/licenses/by-sa/4.0/ . No endorsement is implied.'))
p=head('FIND YOUR WAY','Contents of this volume')
for label,title in [('part1','Primary 1'),('part2','Primary 2'),('part3','Primary 3'),('facts','Multiplication facts'),('AI-1','Discovering AI ? four pages'),('teacher1','Teacher guidance'),('answers1','Lesson answers and methods'),('reviewanswers0','Revision and assessment answers'),('aianswers','AI answers'),('supp0','Teacher objective checks'),('mappingintro','Curriculum evidence and crosswalk'),('glossary0','Glossary'),('credits','Sources and artwork credits'),('book2','Book 2 topic outline')]:
    p+='#grid(columns: (1fr, auto), gutter: 3mm, ['+T(title,12)+'], [#context counter(page).at(<'+label+'>).first()])\n#v(3mm)\n'
p+=note('Lesson lists','The next three pages give each class?s lessons in suggested term groups. Page numbers refer to this bound volume. Use question IDs to find matching answers.')
page('contents',p)
for grade in (1,2,3):
    ls=[l for l in lessons if l['grade']==grade]
    ranges={1:[(1,7),(8,13),(14,19)],2:[(1,7),(8,14),(15,20)],3:[(1,8),(9,16),(17,24)]}[grade]
    content=head(f'PRIMARY {grade}','Our learning journey')+T('Suggested terms • editorial pacing',12,True)+para('Allow about 10 teaching weeks per term plus local revision and assessment time. Each two-page lesson may take several periods. Revisit an idea until pupils can show and explain it. This is not a verified official scheme.')
    for term,(a,b) in enumerate(ranges,1):
        content+=T(f'Term {term}: lessons {a:02}–{b:02}',12,True)
        for l in ls[a-1:b]: content+=f'#grid(columns: (1fr, auto), gutter: 3mm, [{T(l["id"]+"  "+l["title"],10)}], [#context counter(page).at(<{l["id"]}>).first()])\n#v(1mm)\n'
    content+=T('Each term ends with revision. A class assessment follows the final term. Answers and objective checks are in the teacher section.',10)
    page(f'journey{grade}',content)
for grade in (1,2,3):
    ls=[l for l in lessons if l['grade']==grade]
    page(f'part{grade}',head(f'PART {grade}',f'Primary {grade}')+img('artwork/'+({1:'school',2:'market',3:'garden'}[grade])+'.png',110)+para({1:'Start with objects, number words and simple drawings. Count carefully, compare, share and explore the classroom.',2:'Build on tens and ones. Exchange when calculating, explore equal groups, and measure with agreed units.',3:'Explain place value and operations. Compare fractions, measure precisely and organise information to answer questions.'}[grade])+note('A quick beginning check',{1:'Count five objects. Show an empty set. Name one shape. If needed, begin with matching and oral counting.',2:'Read 34, show its tens and ones, find 7 + 5, and recognise a half. Revisit Primary 1 lessons as needed.',3:'Read 146, calculate 28 + 17, show a quarter of eight, and read half past three. Revisit Primary 2 lessons as needed.'}[grade]))
    cuts={1:[7,13,19],2:[7,14,20],3:[8,16,24]}[grade]
    for i,l in enumerate(ls,1):
        fontsize={1:16,2:14.5,3:14}[grade]
        p=head(l['id']+' • LEARN',l['title'])+T('Today: '+l['goal'],11,True)+sec('1','Look and Talk')
        # Scene strips sit above the columns and do not carry quantitative questions.
        p+=img('artwork/'+('market' if l['topic']=='Money' else 'garden' if l['topic'] in ['Length','Weight','Capacity','Area'] else 'school')+'.png',50)+para(l['look'])
        main=sec('2','Learn Together')+para(l['learn'])+'#block(width: 100%, inset: 3mm, radius: 2mm, fill: rgb("eef4ef"))['+T('WORKED EXAMPLE',10,True)+T(l['worked'],{1:14,2:13,3:12.5}[grade])+']\n'
        if l['diagram']:main+='#v(3mm)\n'+img('artwork/diagrams/'+l['diagram']+'.svg',35)
        else:main+='#v(3mm)\n'+T('Show the example with objects or a drawing.',11)+'#v(15mm)\n'
        side=note('WORDS',l['vocabulary'])+'#v(4mm)\n'+note('HINT','Use objects first. Say the number sentence or explain the comparison. Check another way.')+'#v(4mm)\n'+note('TEACHER',l['hint'])
        p+='#grid(columns: (7fr, 3fr), gutter: 5mm, ['+main+'], ['+side+'])\n'
        page(l['id'],p,fontsize)
        p=head(l['id']+' • PRACTISE',l['title'])+sec('3','Try It')
        for j,q in enumerate(l['questions'][:4],1):
            space=24 if any(x in q['prompt'].lower() for x in ['draw','graph','trace']) else 16
            p+=Q(str(j),q['prompt'],space)
        p+=sec('4','Play or Make')+T(l['play'],{1:13.5,2:12.5,3:12}[grade])+'#v(2mm)\n'+sec('5','Check Yourself')
        for j,q in enumerate(l['questions'][4:],5): p+=Q(str(j),q['prompt'],18)
        p+=T('I can do this.  /  I need more practice.',9)
        page(l['id']+'-practice',p,fontsize)
        if i in cuts:
            term=cuts.index(i)+1
            add_review(grade,term) if 'add_review' in globals() else None
    # Reviews are appended immediately below once their authoring data are loaded.
    if grade==3:
        p=head('REFERENCE • PRIMARY 3','Multiplication facts')+para('Read the factor at the left and the factor at the top. Their crossing cell is the product. Build a fact with objects, say it, cover it and check.')
        cells=['[×]']+[f'[{n}]' for n in range(1,10)]
        for a in range(1,10):cells += [f'[{a}]']+[f'[{a*b}]' for b in range(1,10)]
        p+='#table(columns: 10, inset: 3mm, stroke: 0.5pt + teal, fill: (x,y) => if x == 0 or y == 0 {rgb("eaf3e9")} else {white}, '+','.join(cells)+')\n'+para('Find patterns: multiples of 5 end in 0 or 5. Multiples of 2 are even. Swap the two factors and compare the products.')
        page('facts',p)
# Insert authored term reviews at their corresponding positions, and end assessments after each class.
review_data=read('production/reviews.json') if (R/'production/reviews.json').exists() else []
for r in review_data:
    body=head(r['id'],r['title'])+T(r['instruction'],11)+'#v(3mm)\n'
    for i,q in enumerate(r['questions'],1):body+=Q(str(i),q['prompt'],16 if 'draw' in q['prompt'].lower() else 13)
    obj=dict(label=r['id'],body='#set text(size: 13pt)\n'+body)
    index=next(i for i,p in enumerate(pages) if p['label']==r['after'])
    pages.insert(index+1,obj)
# The last four pupil teaching pages are exactly the AI chapter.
ai=[
('AI-1','Meet artificial intelligence','Artificial intelligence, or AI, is a way people build computer systems to do tasks such as recognising pictures or suggesting words. Some AI systems find patterns in many examples. An ordinary calculator follows fixed calculation rules; a device is not AI just because it uses electricity.','Amina sees an app guess the name of a plant from a photograph. An adult explains that the app may use AI. It can still guess wrongly.','Look and Talk: What would you ask before trusting a picture guess?','1. Circle the example that may use AI: a picture-recognition app / a wooden ruler.','Picture-recognition app. A wooden ruler is a physical measuring tool.','2. Tell one thing AI can help people do.','For example recognise patterns in pictures or suggest words; accept a suitable example.'),
('AI-2','Learning from examples','Some AI systems are trained using examples selected by people. They look for patterns rather than learning exactly as a child does. If the examples are few or unrepresentative, the system may make poor guesses on new cases.','Musa shows a pretend learner only red circles. When a blue circle appears, the learner has not seen that colour before. We need circles of varied colours and sizes to test the idea of circle.','Learn Together: Shape is different from colour. A blue circle is still a circle.','1. Draw a red circle and a blue circle. What shape are both?','Both are circles, regardless of colour.','2. Why should examples include different colours and sizes?','So the pattern is not based only on an accidental colour or size feature.'),
('AI-3','Play the example game','No device is needed. Make 8 paper cards: red and blue circles and triangles, with two sizes of each colour-shape combination. An adult helps cut them. Put a shape label on each card.','Training round: show one red circle, one blue circle, one red triangle and one blue triangle. Tell the labels. Hide the labels on the four other cards. Test round: ask a partner to predict each label, then reveal it. Record correct and incorrect guesses. Swap roles. This is a simplified analogy, not a working AI system.','Play or Make: Use shape, not colour, to classify the unseen cards. All materials stay offline.','1. What are the two categories in this game?','Circle and triangle.','2. If 3 of 4 test guesses are correct, how many are incorrect?','1 incorrect; 4 − 3 = 1.'),
('AI-4','Check, ask and keep private','AI can make confident mistakes. Check a mathematical answer using objects, a calculation or a trusted adult. Ask an adult before using an AI app. Do not share your name, photograph, school, address or private family information. You do not need an account or a device for this chapter.','Zainab hears an app say 3 + 4 = 8. She counts seven tops, checks 3 + 4 = 7 with her teacher, and corrects the answer. Daniel says, “A confident answer still needs checking.”','Check Yourself: Explain a safe next step when a device gives a surprising answer.','1. A system says 5 + 2 = 9. Check and correct it.','5 + 2 = 7; show five objects and two more.','2. An app asks for your photo and school name. What should you do?','Stop and ask a trusted adult; do not provide private information.')]
for aid,title,learn,story,activity,q1,a1,q2,a2 in ai:
    p=head('DISCOVERING AI • '+aid,title)+img('artwork/school.png',35)+sec('1','Look and Talk')+para(story)+sec('2','Learn Together')+para(learn)+sec('3','Try It')+Q('1',q1[3:],16)+sec('4','Play or Make')+T(activity,12)+sec('5','Check Yourself')+Q('2',q2[3:],16)
    page(aid,p,13)
# Teacher guidance, contained in the bound volume.
teacher=[
('Teach from evidence','Begin with the part-opening check. Model the idea with objects, draw it, then use symbols. Read instructions aloud when needed. A child may answer orally, point, draw or demonstrate before writing. Use neutral feedback: show what worked, then ask for another check. A correct guess without a method is not the same evidence as a clear demonstration.','Use Look and Talk to identify prior knowledge. In Learn Together, model a worked example. In Try It, watch strategies. In Play or Make, check participation and explanation. In Check Yourself, decide whether to move on, revisit the diagram or teach again in a small group.'),
('Plan time and support','The suggested term groupings are editorial. Match the school calendar and any officially adopted scheme locally. A two-page lesson can take several periods: explore and model; practise; play and assess. Reserve time for retrieval practice and support. Do not race through a page because of the printed term boundary.','For support, reduce the number range, use a larger counter, read the question and model one case. For challenge, ask for another method, a counterexample or a pupil-made problem within the taught scope. Have pupils compare methods without public speed ranking.'),
('Materials, access and safety','Use large clean bottle tops, paper strips, scrap card, string, chalk, a ruler, marked litre container and a simple balance. Avoid small choking hazards, sharp edges, heavy lifting and fuels. Adults supervise cutting, water and improvised balances. No task requires buying materials, internet or personal accounts.','Keep tables and routes accessible. Place shared materials within reach. Use high-contrast outlines and say colour names alongside shape names. Do not make colour the only route to an answer. Offer oral, tactile or partner-supported alternatives. Do not require pupils to reveal home circumstances.'),
('Assessment that guides teaching','Revision pages revisit each suggested term. Class assessments sample the class content; they are not standardised tests or official pass thresholds. Allow quiet practical demonstrations and oral reading support. Record what a pupil can do and what needs another lesson.','For each six-question revision, give one mark for each of questions 1–4, and two marks each for questions 5–6: one for the result and one for a valid method or explanation where requested. For class assessments use one mark per result and one per demonstrated method, up to two per item. Use judgement for drawing and practical rubrics. Do not report a threshold as nationally approved.'),
('Use the answer key','IDs such as P2-04.3 mean Primary 2, lesson 04, question 3. Questions 1–4 are Try It; 5–6 are Check Yourself. Worked examples show a method; answer rubrics accept equivalent correct methods, fraction names and sensible practical results. Additional teacher checks S001 onward supply objective-specific evidence where lesson questions sample a broader skill.','Observe Play or Make: can the pupil follow the rule, count or measure accurately, explain a choice and check? Record independent / prompted / not yet. For a practical result, inspect the method and unit rather than expecting every classroom object to match a fixed answer.'),
('Money and curriculum decisions','This manuscript uses the verified older NERDC mathematics reference. Its money limits are historical: kobo-scale values in Primary 1, amounts up to ₦20 in Primary 2 and 3. Our paper value cards preserve the arithmetic scope. They are not current price or denomination illustrations.','Recognition of genuine Nigerian coins and notes requires verified examples supplied by an adult. Optional historical specimens must be identified as historical. Before publication, the editor should acquire the applicable revised mathematics volumes and ask Gombe SUBEB to confirm adoption and transition arrangements. Never infer current approval from this crosswalk.'),
('Local review and paper proof','Ask Gombe teachers and families to review vocabulary, clothing, classroom materials, story settings, workload and progression. Check varied town and rural experiences and accessible activities. Record specific changes and the reviewer/date in the production review form. No such local review is claimed in this edition.','Print the three sample spreads at Actual size / 100%, with scaling disabled. Check pencil writing and erasing, counter visibility, two-column reading order, contrast and binding margin. Children and teachers should try the activities. Record comfort and corrections before final layout approval.'),
('AI chapter and safeguarding','The four AI pages are enrichment, not a claim that the legacy mathematics curriculum prescribes AI. They need no screen. The classification game is a simplified analogy: humans apply an explicit shape rule, while AI training can be much more complex. Do not describe machines as people or guarantee an AI answer is true.','Use the four page answer rubrics after the main answer key. Keep personal information private. An adult should select and supervise any later optional device use. The chapter’s safety approach is informed by UNICEF guidance on AI and children and its parenting guidance; links are recorded in the sources and credits.')]
for n,(title,a,b) in enumerate(teacher,1):page('teacher'+str(n),head('TEACHER GUIDANCE',title)+para(a)+para(b)+note('Record evidence','Pupil or group code: __________  Date: __________\nObserved skill: ______________________________\nIndependent / prompted / not yet\nNext teaching action: _________________________')+'#v(12mm)\n'+T('Notes and local adaptations',11,True)+'#answerlines(n: 5)\n')
